import{_ as p,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"ajaxHandler() - October CMS - 3.x","titleTemplate":false,"description":"Twig-функция","frontmatter":{"subtitle":"Twig-функция"},"headers":[{"level":2,"title":"Доступ к данным","slug":"доступ-к-данным","link":"#доступ-к-данным","children":[]},{"level":2,"title":"Использование ответов","slug":"использование-ответов","link":"#использование-ответов","children":[]},{"level":2,"title":"Обработка ошибок","slug":"обработка-ошибок","link":"#обработка-ошибок","children":[]},{"level":2,"title":"Обработка перенаправлений","slug":"обработка-перенаправлении","link":"#обработка-перенаправлении","children":[]},{"level":2,"title":"Обработка flash-сообщений","slug":"обработка-flash-сообщении","link":"#обработка-flash-сообщении","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/markup/function/ajax-handler.md","filePath":"3.x/ru/markup/function/ajax-handler.md"}'),u={name:"3.x/ru/markup/function/ajax-handler.md"};function r(d,n,k,g,h,w){const t=s("pre-heading"),e=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"ajaxHandler()",-1)),a(e),n[1]||(n[1]=i(`<p>Функция <code>ajaxHandler()</code> запускает AJAX-обработчик внутри Twig и подготавливает объект ответа <code>Cms\\Classes\\AjaxResponse</code>. Пример вызова обработчика <strong>onResetPassword</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> result <span class="token operator">=</span> ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>В результирующем объекте можно ожидать следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Данные</th></tr></thead><tbody><tr><td><strong>data</strong></td><td>данные, установленные или возвращённые обработчиком, также доступны при прямом вызове объекта.</td></tr><tr><td><strong>error</strong></td><td>во время выполнения обработчика произошла ошибка.</td></tr><tr><td><strong>flash</strong></td><td>flash-сообщения, установленные обработчиком.</td></tr><tr><td><strong>redirect</strong></td><td>обработчик вернул перенаправление.</td></tr></tbody></table></div><h2 id="доступ-к-данным"><a href="#доступ-к-данным" class="header-anchor">#</a> Доступ к данным</h2><p>Переменные, назначенные странице, доступны в результирующем объекте. Рассмотрим следующее определение AJAX-обработчика.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onResetPassword</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;someVariable&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;someValue&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Далее пример вызова обработчика <strong>onResetPassword</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> result <span class="token operator">=</span> ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Переменные <strong>data</strong>, возвращённые обработчиком или установленные на странице во время вызова обработчика, будут доступны через результирующую переменную.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result<span class="token punctuation">.</span>someVariable <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="использование-ответов"><a href="#использование-ответов" class="header-anchor">#</a> Использование ответов</h2><p>При <a href="./../../cms/resources/building-apis.html">создании API в вашей теме</a> ответ можно передать непосредственно в <a href="./response.html">Twig-функцию</a> <code>response()</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>При возврате в качестве ответа данные будут доступны в JSON как свойство <strong>data</strong>.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Переменные страницы не включаются в ответ по соображениям безопасности. Вызовите метод <code>withPageVars</code>, чтобы включить их в ответ.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>withPageVars<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Метод <code>withVars</code> может использоваться для включения дополнительных данных в ответ.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>withVars<span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token string"><span class="token punctuation">&#39;</span>token<span class="token punctuation">&#39;</span></span><span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>foobar<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="обработка-ошибок"><a href="#обработка-ошибок" class="header-anchor">#</a> Обработка ошибок</h2><p>Если во время выполнения обработчика возникает исключение, сообщение об ошибке будет доступно в свойстве <strong>error.message</strong>. Если ошибка является <code>ValidationException</code>, невалидные поля можно найти в свойстве <strong>error.fields</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> result<span class="token punctuation">.</span>error <span class="token delimiter punctuation">%}</span></span>
    An error occurred: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result<span class="token punctuation">.</span>error<span class="token punctuation">.</span>message <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Если возникает исключение, информация об ошибке будет доступна как свойство <strong>error</strong>.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;error&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;An error occurred&quot;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>При возврате ответа из AJAX-обработчика для типа исключения используются следующие коды состояния.</p><div class="table"><table tabindex="0"><thead><tr><th>Исключение</th><th>Код состояния</th></tr></thead><tbody><tr><td><code>ValidationException</code></td><td>422 Unprocessable Entity</td></tr><tr><td><code>ApplicationException</code></td><td>400 Bad Request</td></tr><tr><td><code>Exception</code></td><td>500 Internal Server Error</td></tr></tbody></table></div><h2 id="обработка-перенаправлении"><a href="#обработка-перенаправлении" class="header-anchor">#</a> Обработка перенаправлений</h2><p>Если AJAX-обработчик вызвал перенаправление, оно будет доступно в свойстве <strong>redirect</strong> и может быть возвращено напрямую. Например</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirect</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://octobercms.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Следующий код выполнит перенаправление в браузере в качестве ответа.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onTest<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Объект содержит сообщения <strong>redirect</strong> наряду с данными.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;redirect&quot;</span><span class="token operator">:</span> <span class="token string">&quot;https://octobercms.com&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="обработка-flash-сообщении"><a href="#обработка-flash-сообщении" class="header-anchor">#</a> Обработка flash-сообщений</h2><p>Если были использованы flash-сообщения, они будут доступны в свойстве <strong>flash</strong>. Рассмотрим следующий обработчик в качестве примера.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onTest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test successful&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вызов обработчика и отправка в качестве ответа.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onTest<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вывод содержит <strong>flash</strong>-сообщения наряду с данными.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;flash&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;success&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Test successful&quot;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../cms/resources/building-apis.html">Создание API-ресурсов</a></li></ul></div>`,43))])}const v=p(u,[["render",r]]);export{f as __pageData,v as default};
